use App\Models\{Hazard,HazardType,School,User};use Illuminate\Support\Facades\{DB,Storage};
$school=School::where('name','Sekolah A — Demo Simulasi')->first();$reporter=User::where('email','audit_demo@ruteaman.test')->first();
